func (q *Queries) UpdateLearnerProfile(ctx context.Context, arg UpdateLearnerProfileParams) (LearnerProfile, error) {
	row := q.db.QueryRow(ctx, updateLearnerProfile,
		arg.Nickname,
		arg.SelfDeclaredLevel,
		arg.TargetLevel,
		arg.LearningGoal,
		arg.LearningGoalNote,
		arg.PreferredSpeechSpeed,
		arg.PreferredFormality,
		arg.DialectPreference,
		arg.MemoryEnabled,
		arg.OnboardingCompletedAt,
		arg.At,
		arg.UserID,
	)
	var i LearnerProfile
	err := row.Scan(
		&i.UserID,
		&i.Nickname,
		&i.SelfDeclaredLevel,
		&i.TargetLevel,
		&i.LearningGoal,
		&i.LearningGoalNote,
		&i.PreferredSpeechSpeed,
		&i.PreferredFormality,
		&i.DialectPreference,
		&i.MemoryEnabled,
		&i.OnboardingCompletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

